import os
import sqlite3
import re
import datetime
from functools import wraps

import jwt
from flask import Flask, request, jsonify, g, render_template_string
from passlib.hash import pbkdf2_sha256

APP_SECRET = os.environ.get("APP_SECRET", "dev-secret-change-me")
DB_PATH = "db.sqlite3"

app = Flask(__name__)
app.config["SECRET_KEY"] = APP_SECRET

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                name TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


def make_token(user_id, email):
    payload = {
        "sub": str(user_id),
        "email": email,
        "iat": datetime.datetime.now(datetime.timezone.utc),
        "exp": datetime.datetime.now(datetime.timezone.utc) + datetime.timedelta(hours=12),
    }
    return jwt.encode(payload, APP_SECRET, algorithm="HS256")


def auth_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return jsonify({"message": "Missing or invalid Authorization header"}), 401
        token = auth[7:].strip()
        try:
            data = jwt.decode(token, APP_SECRET, algorithms=["HS256"])
        except jwt.ExpiredSignatureError:
            return jsonify({"message": "Token expired"}), 401
        except jwt.InvalidTokenError:
            return jsonify({"message": "Invalid token"}), 401
        g.user_id = int(data["sub"])
        g.user_email = data.get("email")
        return f(*args, **kwargs)

    return wrapper


def parse_json_body():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return None
    return data


@app.route("/login", methods=["POST"])
def login():
    data = parse_json_body()
    if data is None:
        return jsonify({"message": "Invalid JSON body"}), 400
    email = data.get("email")
    password = data.get("password")
    if not isinstance(email, str) or not isinstance(password, str):
        return jsonify({"message": "Invalid email or password"}), 401
    email = email.strip().lower()
    if not email or not password:
        return jsonify({"message": "Invalid email or password"}), 401

    try:
        db = get_db()
        row = db.execute(
            "SELECT id, email, password_hash FROM users WHERE email = ?", (email,)
        ).fetchone()
    except sqlite3.Error:
        return jsonify({"message": "Internal server error"}), 500

    if row is None:
        return jsonify({"message": "Invalid email or password"}), 401

    try:
        valid = pbkdf2_sha256.verify(password, row["password_hash"])
    except (ValueError, TypeError):
        valid = False

    if not valid:
        return jsonify({"message": "Invalid email or password"}), 401

    token = make_token(row["id"], row["email"])
    return jsonify({"token": token, "message": "Login successful"}), 200


@app.route("/register", methods=["POST"])
def register():
    data = parse_json_body()
    if data is None:
        return jsonify({"message": "Email already in use or invalid data"}), 400
    email = data.get("email")
    password = data.get("password")
    name = data.get("name")
    if not isinstance(email, str) or not isinstance(password, str) or not isinstance(name, str):
        return jsonify({"message": "Email already in use or invalid data"}), 400
    email = email.strip().lower()
    name = name.strip()
    if not EMAIL_RE.match(email) or len(password) < 6 or not name:
        return jsonify({"message": "Email already in use or invalid data"}), 400

    password_hash = pbkdf2_sha256.hash(password)
    try:
        db = get_db()
        db.execute(
            "INSERT INTO users (email, password_hash, name, created_at) VALUES (?, ?, ?, ?)",
            (email, password_hash, name, datetime.datetime.now(datetime.timezone.utc).isoformat()),
        )
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({"message": "Email already in use or invalid data"}), 400
    except sqlite3.Error:
        return jsonify({"message": "Internal server error"}), 500

    return jsonify({"message": "Registration successful"}), 201


@app.route("/me", methods=["GET"])
@auth_required
def me():
    try:
        db = get_db()
        row = db.execute(
            "SELECT id, email, name FROM users WHERE id = ?", (g.user_id,)
        ).fetchone()
    except sqlite3.Error:
        return jsonify({"message": "Internal server error"}), 500
    if row is None:
        return jsonify({"message": "User not found"}), 404
    return jsonify({"id": row["id"], "email": row["email"], "name": row["name"]}), 200


