  button { margin-top:1rem; width:100%; padding:.6rem; border:0; border-radius:6px; background:#2563eb; color:#fff; font-weight:600; cursor:pointer; }
  button:hover { background:#1d4ed8; }
  .msg { margin-top:1rem; font-size:.85rem; }
  .err { color:#b91c1c; }
  .ok { color:#047857; word-break:break-all; }
  .tabs { display:flex; gap:.5rem; margin-bottom:1rem; }
  .tabs button { margin-top:0; background:#e5e7eb; color:#111; }
  .tabs button.active { background:#2563eb; color:#fff; }
  .hidden { display:none; }
</style>
</head>
<body>
<div class="card">
  <div class="tabs">
    <button id="tab-login" class="active" type="button">Login</button>
    <button id="tab-register" type="button">Register</button>
  </div>
  <form id="login-form">
    <h1>Sign in</h1>
    <label for="l-email">Email</label>
    <input id="l-email" type="email" required autocomplete="username">
    <label for="l-password">Password</label>
    <input id="l-password" type="password" required autocomplete="current-password">
    <button type="submit">Login</button>
  </form>
  <form id="register-form" class="hidden">
    <h1>Create account</h1>
    <label for="r-name">Name</label>
    <input id="r-name" type="text" required autocomplete="name">
    <label for="r-email">Email</label>
    <input id="r-email" type="email" required autocomplete="username">
    <label for="r-password">Password</label>
    <input id="r-password" type="password" required minlength="6" autocomplete="new-password">
    <button type="submit">Register</button>
  </form>
  <div id="msg" class="msg"></div>
</div>
<script>
const msg = document.getElementById('msg');
const loginForm = document.getElementById('login-form');
const registerForm = document.getElementById('register-form');
const tabLogin = document.getElementById('tab-login');
const tabRegister = document.getElementById('tab-register');

function show(el, text, ok) {
  el.textContent = text;
  el.className = 'msg ' + (ok ? 'ok' : 'err');
}

tabLogin.onclick = () => {
  loginForm.classList.remove('hidden');
  registerForm.classList.add('hidden');
  tabLogin.classList.add('active');
  tabRegister.classList.remove('active');
  msg.textContent = '';
};
tabRegister.onclick = () => {
  registerForm.classList.remove('hidden');
  loginForm.classList.add('hidden');
  tabRegister.classList.add('active');
  tabLogin.classList.remove('active');
  msg.textContent = '';
};

loginForm.onsubmit = async (e) => {
  e.preventDefault();
  const body = {
    email: document.getElementById('l-email').value,
    password: document.getElementById('l-password').value
  };
  try {
    const res = await fetch('/login', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(body)
    });
    const data = await res.json();
    if (res.ok) {
      show(msg, 'Login successful. Token: ' + data.token, true);
    } else {
      show(msg, data.message || 'Login failed', false);
    }
  } catch (err) {
    show(msg, 'Network error', false);
  }
};

registerForm.onsubmit = async (e) => {
  e.preventDefault();
  const body = {
    name: document.getElementById('r-name').value,
    email: document.getElementById('r-email').value,
    password: document.getElementById('r-password').value
  };
  try {
    const res = await fetch('/register', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(body)
    });
    const data = await res.json();
    if (res.ok) {
      show(msg, 'Registration successful. You can now log in.', true);
    } else {
      show(msg, data.message || 'Registration failed', false);
    }
  } catch (err) {
    show(msg, 'Network error', false);
  }
};
</script>
</body>
</html>
"""


@app.route("/", methods=["GET"])
def index():
    return render_template_string(LOGIN_PAGE)


@app.errorhandler(404)
def not_found(e):
    return jsonify({"message": "Not found"}), 404


@app.errorhandler(405)
def method_not_allowed(e):
    return jsonify({"message": "Method not allowed"}), 405


@app.errorhandler(500)
def server_error(e):
    return jsonify({"message": "Internal server error"}), 500


init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
